class FeaturedCollections extends HTMLElement{constructor(){super(),this.tabs=this.querySelectorAll('[data-action="toggle-tab"]'),this.link=this.querySelector(".FeaturedCollections__CollectionLink"),this.arrows=this.querySelectorAll("[data-scroll]"),this.tabs.forEach(t=>{t.addEventListener("click",()=>this.changeCollectionLink(t))}),this.arrows.forEach(t=>{t.addEventListener("click",()=>this.scrollArrows(t))})}changeCollectionLink(t){this.link.setAttribute("href",t.dataset.linkUrl),this.link.innerHTML=t.dataset.linkTitle}scrollArrows(t){const e=t.dataset.scroll,l=t.closest(".FeaturedCollections__ProductsTabs");l.scrollLeft="next"===e?l.offsetWidth:0}}customElements.define("featured-collections",FeaturedCollections);